// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(uint256 seed) public {
        // Map the fuzzed seed onto the deciding boundary {zero, non-zero} without
        // hard-coding a value: the fuzzer chooses whether the new owner is 0 or not.
        address newOwner = address(uint160(seed % 2));

        // The deployer of setUp (this test contract) is the owner after initialize.
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: ownership is NEVER transferred to the zero address.
        // Reference: zero-address transfer reverts (ok == false) so owner() != 0 holds.
        // Mutant: succeeds and sets owner to 0, breaking the rule.
        assertTrue(!(ok && c.owner() == address(0)));
    }
}
